public class Main {

    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            solve(in);
        }
    }

    private static void solve(Scanner in) {
        in.useDelimiter("\\D");
        int howM = in.nextInt();
        int intX = in.nextInt();
        int[] dmax = new int[howM + 1];
        for (int i = 1; i < dmax.length; i++) {
            dmax[i] = i;
        }
        while (intX --> 0) {
            int a = in.nextInt();
            int inR = in.nextInt();

            int tmp = dmax[a];
            dmax[a] = dmax[inR];
            dmax[inR] = tmp;
        }
        for (int i = 1; i < dmax.length; i++) {
            System.out.println(dmax[i]);
        }
    }
}

