import java.util.Scanner;


public class Main{

	public static void main(String[] args) {

		Scanner min_ = new Scanner(System.in);
		int a = min_.nextInt();
		int[] max_profit = new int[a];
		String count_Tle[] = new String[a];
		String str = "";

		for(int Rmin=0 ; Rmin<count_Tle.length ; Rmin++) {
			max_profit[Rmin] = min_.nextInt();
		}
		String maxR = "";
		for(int in_T=0 ; in_T<max_profit.length ; in_T++) {
			maxR += max_profit[in_T];
			if(in_T+1<max_profit.length)
				maxR += " ";
		}
		System.out.println(maxR);
		solve(max_profit);
	}

	public static void solve(int[] max_profit) {
		for(int Rmin=1 ; Rmin<max_profit.length ; Rmin++) {
			int targetV = max_profit[Rmin];
			int format = Rmin - 1;
			while(format >= 0 && max_profit[format] > targetV) {
				max_profit[format + 1] = max_profit[format];
				format--;
			}
			max_profit[format + 1] = targetV;
			String maxR = "";
			for(int in_T=0 ; in_T<max_profit.length ; in_T++) {
				maxR += max_profit[in_T];
				if(in_T+1<max_profit.length)
					maxR += " ";
			}
			System.out.println(maxR);
		}
	}
}

