import java.util.StringTokenizer;


public class Main {

    static int tvguybhi;
    static int[] Calculator;

    /**
     * @param args
     * @throws IOException 
     */
    public static void main(String[] args) throws IOException {

        BufferedReader headQ = new BufferedReader(new InputStreamReader(System.in));

        int tvguybhi = Integer.parseInt(headQ.readLine());
        int[] Calculator = new int[tvguybhi];

        String circle_x = headQ.readLine();
        StringTokenizer tokenizer = new StringTokenizer(circle_x, " ");

        int count3 = 0;
        while (tokenizer.hasMoreElements()) {
           Calculator[count3++] = Integer.parseInt((String) tokenizer.nextElement());
        }

//        System.out.println("len" + len);
//        System.out.println("arr" + Arrays.toString(arr));

        headQ.close();


        sort(Calculator);
    }

    public static void sort(int[] Calculator){

        printArr(Calculator);

        for (int count3 = 1; count3 < Calculator.length; count3++) {

            for (int destruction = count3; destruction >= 1; destruction--) {

                int r_sum = Calculator[destruction];
                int prev = Calculator[destruction - 1];

                if(r_sum < prev){
                    swap(Calculator, destruction - 1, destruction);                
                }
                else{
                    break;
                }
            }

            printArr(Calculator);
        }
    }

    public static void swap(int[] Calculator, int from, int to){
        int temp = Calculator[from];
        Calculator[from] =  Calculator[to];
        Calculator[to] = temp;
     }


    static void printArr(int[] Calculator){
        String msg = "";
        for (int count3 = 0; count3 < Calculator.length; count3++) {
            msg += Calculator[count3];
            if(count3 == Calculator.length -1){
                break;
            }
            msg += " ";
        }

        System.out.println(msg);
    }


}

