		int powM = in.nextInt();
		System.out.println(gcd(nS,powM));
	}

	public static int gcd(int x, int num_c) {
		if (x % num_c == 0) {
			return num_c;
		}
		else {
			return gcd(num_c, x % num_c);
		}
	}
}

