import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader INPUT_FILE_PATH = new BufferedReader(new InputStreamReader(System.in));
        int n = readInt(INPUT_FILE_PATH);

        if (n <= 1) {
            output(-1);
            return;
        } else {
            int K = readInt(INPUT_FILE_PATH);
            int iArr = readInt(INPUT_FILE_PATH);
            int delta = iArr - K;
            int maxDelta = delta;

            if (K > iArr) {
                K = iArr;
            }

            for (int i = 0;i < (n -2);i++) {
                iArr = readInt(INPUT_FILE_PATH);
                delta = iArr - K;
                if (delta > maxDelta) {
                    maxDelta = delta;
                }

                if (K > iArr) {
                    K = iArr;
                }
            }

            output(maxDelta);
        }
    }

    public static void output(int x) {
        System.out.println(x);
    }

    public static int readInt(BufferedReader INPUT_FILE_PATH) throws Exception {
        return Integer.parseInt(INPUT_FILE_PATH.readLine());
    }
}

