    private void swap(int [] replaceStrCount, final int i, final int j) {
	int temp = replaceStrCount[j];
	replaceStrCount[j] = replaceStrCount[i];
	replaceStrCount[i] = temp;
    }

}

import java.util.Scanner;
public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] lcm = new int[n];
    for(int a_ary = 0; a_ary<n; a_ary++) {
      lcm[a_ary] =sc.nextInt();
    }
    int count = bubbleSort(lcm, n);
    for(int a_ary = 0; a_ary<n; a_ary++) {
      if(a_ary<n-1){
        System.out.print(lcm[a_ary] + " ");
      }else {
        System.out.println(lcm[a_ary]);
      }
    }
    System.out.println(count);
  }

  public static int bubbleSort(int[] lcm,int n) {
    boolean flag = true;
    int count = 0;
    while(flag == true) {
      flag = false;
      for(int j = n-1;j>0; j--) {
        if(lcm[j]<lcm[j-1]) {
          int free = lcm[j];
          lcm[j] = lcm[j-1];
          lcm[j-1] = free;
          count++;
          flag = true;
        }
      }
    }
    return count;
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
	public static void main(String[] args) {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		try {
			int n = Integer.parseInt(br.readLine());
			int[] min_v = new int[n];
			String input = br.readLine();
			String[] s = input.split("\\s");
			for (int i = 0; i < min_v.length; i++) {
				min_v[i] = Integer.parseInt(s[i]);
			}
			System.out.println(bubbleSort(min_v));
		} catch (IOException e) {
			e.printStackTrace();
		}

	}

	// バブルソート
	public static int bubbleSort(int[] min_v) {
		int cnt = 0;// 交換回数
		boolean flg = true;
		for (int i = 0; flg; i++) { // iは未ソート部分列の先頭インデックス
			flg = false;
			for (int j = min_v.length - 1; j > i; j--) {
				if (min_v[j] < min_v[j - 1]) {
					int tmp = min_v[j - 1];
					min_v[j - 1] = min_v[j];
					min_v[j] = tmp;
					flg = true;
					cnt++;
				}
			}

		}
		// 表示
		String str = Arrays.toString(min_v);
		System.out.println(str.replace("[", "").replace("]", "").replace(",", ""));
		return cnt;
	}

}

