		int doubleArray[] = new int[n];

		for(maxup = 0; maxup < n; maxup++){
			doubleArray[maxup] = sc.nextInt();
		}

		selectionsort(n, doubleArray);
	}
	public static void selectionsort(int n, int doubleArray[]){
		int arrayOutput = 0;
		for (int maxup = 0; maxup <= n - 1; maxup++){
			int room = maxup;
			for(int j = maxup; j <= n - 1; j++){
				if(doubleArray[j] < doubleArray[room]){
					room = j;
				}
			}
			if(doubleArray[maxup] != doubleArray[room]) arrayOutput++;
			int temp = doubleArray[maxup];
			doubleArray[maxup] = doubleArray[room];
			doubleArray[room] = temp;
		}
		for(int maxup = 0; maxup < n; maxup++){
			if(maxup == n - 1) System.out.println(doubleArray[maxup]);
			else System.out.print(doubleArray[maxup] + " ");
		}
		System.out.println(arrayOutput);
	}
}

