class Queue{
	int prev_person;
	int endIndex;
	int size;
    String[] queueName;
    int[] operator;

	Queue(int debt){
    	prev_person =0;
    	endIndex = 0;
    	size = debt;
        queueName = new String[debt];
        operator = new int[debt];
	}
	void enqueue(Process sf){
		//System.out.println("??¨????????\???"+process.getProcessName()+","+process.getProcessTime());

		queueName[endIndex]=sf.getProcessName();
		operator[endIndex]=sf.getProcessTime();
		endIndex++;
		endIndex %= size;
	}
	Process dequeue(){
		//System.out.println("????????\???"+queueName[startIndex]+","+queueTime[startIndex]);
		if(queueName[prev_person].equals("")){
			return null;
		}
		Process sf = new Process(queueName[prev_person],operator[prev_person]);
		queueName[prev_person]="";
		prev_person++;
		prev_person %= size;
		return sf;
	}
}

