     // accessing the numbers in the second line
        for (int i = 0; i < checkPrime.length; i++){
        	checkPrime[i] = in.nextInt();
        }

        int res = binarySearch(intArray1, checkPrime);

        System.out.println(res);
        in.close();
    }
}

