public class Main {

	public static int totalMatches(int[] array, int[] primeAr) {
		int total=0;
		for (int i = 0; i < primeAr.length; i++) {
			if (Binarysearch(array, primeAr[i])) {
				total++;
			}
		}
		return total;
	}

	public static boolean Binarysearch( int[] array,  int search) {
		int left = 0;
		int right = array.length - 1;

		while ( left <= right) {
			int mid = (right+left)/2;
			if(array[mid] < search) {
				left = mid + 1;
			}
			else if(array[mid] > search) {
				right = mid - 1;
			}
			else {
				return true;
			}
		}
		return false;

	}

