public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		while(true) {
			int n = sc.nextInt();

			if(n == 0) break;

			int[] isSpaceChar = new int[n];

			int sum = 0;
			for (int qry = 0; qry < n; qry++) {
				isSpaceChar[qry] = sc.nextInt();
				sum += isSpaceChar[qry];
			}
			double ave = (double)sum/n;

			double index_prevMax = 0;
			for (int qry = 0; qry < n; qry++) {
				double tmp = isSpaceChar[qry] - ave;
				index_prevMax += tmp * tmp;
			}
			index_prevMax = Math.pow(index_prevMax/n, 0.5);

			System.out.println(index_prevMax);
		}
	}
}

