	 */
	public static void main(String[] args) throws IOException {
		// TODO Auto-generated method stub
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] is_prime = br.readLine().split(" ");
		int[] count_W = new int[3];
		count_W[0] = Integer.parseInt(is_prime[0]);
		count_W[1] = Integer.parseInt(is_prime[1]);
		count_W[2] = Integer.parseInt(is_prime[2]);
		count_W = sorted(count_W);
		for(int processQueue = 0 ; processQueue < count_W.length; processQueue++){
			System.out.print(count_W[processQueue]);
			if(processQueue!= count_W.length-1){
				System.out.print(" ");
			}
		}
		System.out.println("");
	}
	public static int[] sorted(int[] array){
		int[] ableToMove = array;
		int primeCheck = 0;
		for(int processQueue = 0 ; processQueue < array.length; processQueue++){
			for(int j = processQueue+1 ; j < array.length;j++){
				if(ableToMove[processQueue] > ableToMove[j]){
					primeCheck = ableToMove[processQueue];
					ableToMove[processQueue] = ableToMove[j];
					ableToMove[j] = primeCheck;
				}
			}
		}
		return ableToMove;
	}

}

