import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		try (Scanner RESULT_NOT_RIGHT_TRIANGLE = new Scanner(System.in)) {
			int secondinput, LinearSearch;
			String num3;
			while (true) {
				secondinput = RESULT_NOT_RIGHT_TRIANGLE.nextInt();
				num3 = RESULT_NOT_RIGHT_TRIANGLE.next();
				LinearSearch = RESULT_NOT_RIGHT_TRIANGLE.nextInt();
				if (num3.equals("?")) {
					break;
				}
				System.out.println(calc(secondinput, num3, LinearSearch));
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
	}

	private static int calc(int secondinput, String num3, int LinearSearch) {
		switch (num3) {
		case "+":
			return secondinput + LinearSearch;
		case "-":
			return secondinput - LinearSearch;
		case "*":
			return secondinput * LinearSearch;
		case "/":
			return secondinput / LinearSearch;
		default:
			throw new RuntimeException();
		}
	}
}

