import java.util.Scanner;

public class Main {
    public static void main(String[] args) {

    	/*Scanner = テキスト入力を扱うためのクラス
		 *キーボードからの入力を受けつける場合は
		 *System.inを使って下記のように記述
		 */
		Scanner scan = new Scanner(System.in);

		int enqueue1 = scan.nextInt();

		/*long型でConstraintsの条件を記述してみました。
		 *maxに-1000000 minに1000000を設定。
		 *jがiの長さを変えるまでforループで回す。
		 *if文でmax、min内の値を入れ替える。
		 */
		long deQueue = -1000000, now_time = 1000000, sum = 0;
		for(int arraySizeS2 = 0; arraySizeS2 < enqueue1; arraySizeS2++){
			long numberOfProcesses = scan.nextLong();
			sum = sum + numberOfProcesses;
			if(numberOfProcesses > deQueue){deQueue = numberOfProcesses;}
			if(numberOfProcesses < now_time){now_time = numberOfProcesses;}

		}
		/*条件を終えたらfor文を抜けmin max sumの順に表示
		 * 空白の指示が出てるので空白もはさむ。
		 */
		System.out.println(now_time +" "+ deQueue +" "+sum);

    }
}

