public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner sc = new Scanner(System.in);

    void solve() {
        String str;
        while (true) {
            str = sc.nextLine();
            String[] sp = str.split(" ");
            int rng = Integer.parseInt(sp[0]);
            int sosuu = Integer.parseInt(sp[1]);
            if (isFin(rng, sosuu)) break;
            System.out.println(sim(rng, sosuu));
        }
    }

    int sim(int rng, int sosuu) {
        int cnt = 0;
        for (int i = 1; i <= rng; ++i) {
            for (int j = i + 1; j <= rng; ++j) {
                if (i == j) continue;
                int k = sosuu - i - j;
                if (i == k || j == k) continue;
                if (j < k && k <= rng) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    boolean isFin(int rng, int sosuu) {
        return rng == 0 && sosuu == 0;
    }

}

