			for (int x = 0; x < n+1; x++){
				if (x < n){
					for (int isPrime = 0; isPrime < min_price_after+1; isPrime++){
						if(isPrime < min_price_after){
							newTable[x][isPrime] = table[x][isPrime];
							sumAll += newTable[x][isPrime];
						}else{
							for (int a = 0; a < min_price_after; a++){
								sumY[x] += table[x][a];
								newTable[x][isPrime] = sumY[x];
							}
						}
