public class Main {

    /**
     * @param args the command line arguments
     */
    public static void main(String[] args) throws IOException {

        int time_array = 0;
        int double_a = 0;

        int l = 0;
        int totTime[][] = new int[100][100];
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            java.util.StringTokenizer st = new StringTokenizer(line, " ");
            while (st.hasMoreTokens()) {
                if (time_array == 0 && double_a == 0) {
                    time_array = Integer.parseInt(st.nextToken());
                    double_a = Integer.parseInt(st.nextToken());
                } else {
                    for (int i = 0; i < double_a; i++) {
                        totTime[l][i] = Integer.parseInt(st.nextToken());
                    }
                    l++;
                }
            }
            if (l == time_array) {
                break;

            }

        }
        int sum = 0;
        int ans_matrix[][] = new int[time_array + 1][double_a + 1];
        for (int i = 0; i < time_array; i++) {
            for (int j = 0; j < double_a; j++) {
                ans_matrix[i][j] = totTime[i][j];
                ans_matrix[i][double_a] += totTime[i][j];
            }
            sum += ans_matrix[i][double_a];
        }
        for (int i = 0; i < time_array; i++) {
            for (int j = 0; j < double_a; j++) {
                ans_matrix[time_array][j] += totTime[i][j];
            }
        }
        ans_matrix[time_array][double_a] = sum;

        for (int i = 0; i < ans_matrix.length; i++) {
            for (int j = 0; j < ans_matrix[i].length; j++) {
                System.out.print(ans_matrix[i][j]);
                if (!(j == double_a)) {
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }
}

