public class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n, initializeQ, primeList;
		n = in.nextInt();
		initializeQ = in.nextInt();
		primeList = in.nextInt();
		long global_timer[][] = new long[n][initializeQ];
		long count_Empty[][] = new long[initializeQ][primeList];

		for(int n_gcd=0;n_gcd<n;n_gcd++) {
			for(int nyuryoku=0;nyuryoku<initializeQ;nyuryoku++) {
				global_timer[n_gcd][nyuryoku] = in.nextInt();
			}
		}
		for(int n_gcd=0;n_gcd<initializeQ;n_gcd++) {
			for(int nyuryoku=0;nyuryoku<primeList;nyuryoku++) {
				count_Empty[n_gcd][nyuryoku] = in.nextInt();
			}
		}

		long c[][] = new long[n][primeList];
		for(int n_gcd=0;n_gcd<n;n_gcd++) {
			for(int nyuryoku=0;nyuryoku<primeList;nyuryoku++) {
				for(int k=0;k<initializeQ;k++) {
