		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		int bufferPointer = scan.nextInt();
		int linesum = scan.nextInt();
		int[][] vectorA = new int[n][bufferPointer];
		int[][] helper = new int[bufferPointer][linesum];
		long[][] MAX_F = new long[n][linesum];
		for(int taroList = 0; taroList < n; taroList++){
			for(int array = 0; array < bufferPointer; array++){
				int elm =scan.nextInt();
				vectorA[taroList][array] = elm;
			}
		}
		for(int taroList = 0; taroList < bufferPointer; taroList++){
			for(int array = 0; array < linesum; array++){
				int elm = scan.nextInt();
				helper[taroList][array] = elm;
			}
		}

		for(int taroList = 0; taroList < n; taroList++){
			for(int array = 0; array < linesum; array++){
				long ans = 0;
				for(int ind = 0; ind < bufferPointer; ind++){
					ans += (long) vectorA[taroList][ind] * (long) helper[ind][array];

