public class Main {

	static int solve(String s, String ground) {
		int min = 1001;

		for (int i = 0; i < s.length() - ground.length() + 1; i++) {
			int count = 0;
			for (int j = 0; j < ground.length(); j++) {
				if (s.charAt(i + j) != ground.charAt(j))
					count++;
			}
			if (count < min)
				min = count;
		}

		return min;
	}

	public static void main(String[] args) {
		Scanner stdIn = new Scanner(System.in);

		String s, ground;
		s = stdIn.next();
		ground = stdIn.next();
		int result = solve(s, ground);
		System.out.println(result);

		stdIn.close();
	}
}

