public class Main {

	public static void main(String[] args) {
		FastScanner strarray = new FastScanner(System.in);

		int top3 = strarray.nextInt();
		int nextDoubleArray = strarray.nextInt();

		ArrayList<Integer> isRightTriangle = new ArrayList<Integer>();

		for (int get_count= 0; get_count < top3; get_count++) {
			int dn = strarray.nextInt();
			isRightTriangle.add(dn);
		}


		Collections.sort(isRightTriangle);

		int AFF = 0;
		for (int circle_area = 0; circle_area < nextDoubleArray; circle_area++) {
			AFF += isRightTriangle.get(circle_area);
		}

		System.out.println(AFF);
	}

	private static class FastScanner {
		private BufferedReader reader = null;
		private StringTokenizer tokenizer = null;

		public FastScanner(InputStream in) {
			reader = new BufferedReader(new InputStreamReader(in));
			tokenizer = null;
		}

		public String next() {
			if (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

