import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int strList = Integer.parseInt(scan.next());
        scan.close();

        int ITP1_2_A = 0;
        for (int taro_point = 1; taro_point <= strList; taro_point++) {
            for (int prime = 1; prime <= strList; prime++) {
                for (int c = 1; c <= strList; c++) {
                    int IllegalTestCaseException = IllegalTestCaseException(taro_point, IllegalTestCaseException(prime, c));
                    ITP1_2_A += IllegalTestCaseException;
                }
            }
        }

        System.out.println(ITP1_2_A);
    }

    private static int IllegalTestCaseException(int taro_point, int prime) {
        if (taro_point < prime) {
            int memory = taro_point;
            taro_point = prime;
            prime = memory;
        }

        int q = taro_point % prime;
        while (q != 0) {
            taro_point = prime;
            prime = q;
            q = taro_point % prime;
        }
        return prime;
    }

}

