import java.util.Scanner;

class Main {
  public static void main(String[] args) {
    Scanner s = new Scanner(System.in);
    int numR = s.nextInt();
    int run = s.nextInt();
    int[] kosu = new int[run];
    int f_num = numR;
    for(int i = 0; i < run; i++) {
      kosu[i] = s.nextInt();
    }
    if(run == 2) {
      f_num = kosu[1]-kosu[0];
    } else {
      for(int i = 1; i < run; i++) {
        int y = kosu[i-1]+numR-kosu[i];
        if(f_num > y) {
          f_num = y;
        }
      }
      int x = kosu[run-1]-kosu[0];
      if(f_num > x) {
        f_num = x;
      }
    }

    System.out.println(f_num);
  }
}

