public class Main{
	public static void main(String args[]){
		Scanner sc = new Scanner(System.in);
		String n = sc.next();
		long chg = Long.parseLong(n);
		String pi = sc.next();
		long mask = Long.parseLong(pi);
		String duration = sc.next();
		long B = Long.parseLong(duration);
		long ans;
		long mult = chg / (mask + B);
		long ex = chg - (mask + B) * mult;
		if(mask == 0){
			ans = 0;
		}else{
			ans = mult * mask;
			if(ex <= mask){
				ans += ex;
			}else{
				ans += mask;
			}
		}
		System.out.println(ans);
	}
}

