import java.io.IOException;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) throws IOException {

		Scanner scan = new Scanner(System.in);
		int upperLimmitX;
		upperLimmitX = scan.nextInt();

		if (upperLimmitX % 2 == 0) {
			System.out.println(upperLimmitX / 2);
		} else {
			System.out.println(upperLimmitX / 2 + 1);
		}

	}

	/**
	 * 余りを求める。
	 * @param a
	 * @param b
	 * @return 余り。余りがマイナスの時はプラスで返す。ｓ
	 */
	public static long myMod(long room, long enzanshi) {
		long ret = 0;

		ret = room % enzanshi;

		if (ret < 0) {
			ret += enzanshi;
		}

		return ret;
	}

	/**
	 * 乗数を求める ※mod対応
	 * @param a 基数
	 * @param n 乗数
	 * @param primeNumMod 法 mod値 使わない場合は「0」
	 * @return
	 */
	public static long myModPow(long room, long upperLimmitX, long totals) {

		long ans = 1;

		//乗数が0の場合→1
		if (upperLimmitX == 0)
			return 1;

		if (totals == 0) {
			//modを使わないとき

			while (upperLimmitX > 0) {

				if (upperLimmitX % 2 == 0) {
					//累乗が偶数の時

					room *= room;
					upperLimmitX = upperLimmitX / 2;
				} else {
					//累乗が奇数の時
					ans *= room;
					upperLimmitX--;
				}
			}

			return ans;

		} else {
			//modを使うとき

			//初めに桁を落とす
			room = myMod(room, totals);

			while (upperLimmitX > 0) {

				if (upperLimmitX % 2 == 0) {
					//累乗が偶数の時

					room *= myMod(room, totals);
					upperLimmitX = upperLimmitX / 2;

				} else {
					//累乗が奇数の時
					ans *= myMod(room, totals);
					upperLimmitX--;

				}
			}

			return myMod(ans, totals);

		}

	}

}

