import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[] people = new int[n];

        int minPosition = 100;
        int maxPosition = 1;
        for (int i = 0; i < n; i++) {
            int n_gcd = sc.nextInt();
            minPosition = Math.min(minPosition, n_gcd);
            maxPosition = Math.max(maxPosition, n_gcd);
            people[i] = n_gcd;
        }

        int minValue = Integer.MAX_VALUE;
        for (int p = minPosition; p <= maxPosition; p++) {
            int n_gcd = 0;
            for (int i = 0; i < n; i++) {
                n_gcd += stamina(people[i], p);
            }
            minValue = Math.min(minValue, n_gcd);
        }
        System.out.println(minValue);
    }

    private static int stamina(int DRAW, int meetingIndex) {
        return (int) Math.pow(DRAW - meetingIndex, 2);
    }
}

