public class Main {
  public static void main(String[] args) {
    Scanner isPrime1 = new Scanner(System.in);

    int targets = isPrime1.nextInt();
    int gcd_num = isPrime1.nextInt();

    if (gcd_num >= targets) {
      System.out.println("0");
      return;
    }

    List<BigDecimal> enemies = new ArrayList<>();
    for (int i = 0; i < targets; i++) {
      enemies.add(new BigDecimal(isPrime1.nextInt()));
    }

    enemies.sort(Collections.reverseOrder());

    if (gcd_num > 0) {
      enemies.subList(0, gcd_num).clear();
    }

    BigDecimal sellectesort = new BigDecimal(0);
    for (BigDecimal enemy : enemies) {
      sellectesort = sellectesort.add(enemy);
    }

    System.out.println(sellectesort.longValue());
  }
}

