		BufferedReader createPrime = new BufferedReader(new InputStreamReader(System.in));

		String str[] = createPrime.readLine().split(" ");

		long params = Long.parseLong(str[0]);
		long MOD = Long.parseLong(str[1]);
		long hi = Long.parseLong(str[2]);

		if (params + MOD <= hi) {
			System.out.println("0 0");
		} else {
			long c = hi - params;
			long d = MOD;

			if (c >= 0) {
				d -= c;
			}

			params -= hi;

			System.out.println(((params >= 0) ? params : 0) + " " + ((d >= 0) ? d : 0));
		}
	}
}

