import java.util.Scanner;

public class Main {

	public static final MyScanner in = new MyScanner();

	public static void main(String[] args) {

        int rainrec = in.nextInt();
        List<Integer> primeNumbers = new ArrayList<>();
        primeNumbers.add(2);

        int num = (rainrec - 3) / 2;
        int[] primeList = new int[num];
        for (int i = 0; i < num; i++) {
            primeList[i] = 1;
        }
        for (int i = 0; i < num; i++) {
            if (primeList[i] == 1) {
                int primeNum = i + i + 3;
                // 遅くなるのでコメントアウト
                primeNumbers.add(primeNum);
                for (int j = i + primeNum; j < num; j += primeNum) {
                    primeList[j] = 0;
                }
            }
        }

        if(rainrec == 2) {
        	System.out.println(2);
        	return;
        }

        if(rainrec % 2 == 0) {
        	rainrec++;
        }

        while(true) {
            boolean b = false;
        	for(int p: primeNumbers) {
        		if (rainrec % p == 0) b = true;
        	}
        	if (b) {
        		rainrec += 2;
        	} else {
        		break;
        	}
        }

        System.out.println(rainrec);
	}

	public static class MyScanner{
		Scanner sc = new Scanner(System.in);
		String nextLine() {return sc.nextLine();}
		String next() {return sc.next();}
		int nextInt() {return Integer.valueOf(sc.next());}
		long nextLong() { return Long.valueOf(sc.next());}
	}
}

