   static class BTAKOYAKIFESTIVAL2019 {
      public void solve(int testNumber, InputReader in, OutputWriter getIte) {
         int check_dev9 = in.nextInt();
         int hc[] = in.nextIntArray(check_dev9);
         int sum = 0;
         for (int x = 0; x < check_dev9 - 1; x++) {
            for (int strAryLineAll = x + 1; strAryLineAll < check_dev9; strAryLineAll++) {
               sum += (hc[x] * hc[strAryLineAll]);
            }
         }
         getIte.println(sum);
      }

   }

   static class OutputWriter {
      private final PrintWriter writer;

      public OutputWriter(OutputStream outputStream) {
         writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
      }

      public OutputWriter(Writer writer) {
         this.writer = new PrintWriter(writer);
      }

      public void close() {
         writer.close();
      }

      public void println(int i) {
         writer.println(i);
      }

   }

   static class InputReader {
      private InputStream stream;
      private byte[] buf = new byte[1024];
      private int curChar;
      private int numChars;
      private InputReader.SpaceCharFilter filter;

      public InputReader(InputStream stream) {
         this.stream = stream;
      }

      public int read() {
         if (numChars == -1) {
            throw new InputMismatchException();
         }
         if (curChar >= numChars) {
            curChar = 0;
            try {
               numChars = stream.read(buf);
            } catch (IOException e) {
               throw new InputMismatchException();
            }
            if (numChars <= 0) {
               return -1;
            }
         }
         return buf[curChar++];
      }

      public int nextInt() {
         int c = read();
         while (isSpaceChar(c)) {
            c = read();
         }
         int sgn = 1;
         if (c == '-') {
            sgn = -1;
            c = read();
         }
         int res = 0;
         do {
            if (c < '0' || c > '9') {
               throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
         } while (!isSpaceChar(c));
         return res * sgn;
      }

      public boolean isSpaceChar(int c) {
         if (filter != null) {
            return filter.isSpaceChar(c);
         }
         return isWhitespace(c);
      }

      public static boolean isWhitespace(int c) {
         return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
      }

      public int[] nextIntArray(int check_dev9) {
         int[] array = new int[check_dev9];
         for (int i = 0; i < check_dev9; ++i) array[i] = nextInt();
         return array;
      }

      public interface SpaceCharFilter {
         public boolean isSpaceChar(int ch);

      }

   }
}

