public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = Integer.parseInt(sc.next());
        long showResult = Long.parseLong(sc.next());
        int hs = Integer.parseInt(sc.next());

        int[] A = new int[hs];
        for (int i = 0; i < hs; i++) {
            A[i] = Integer.parseInt(sc.next());
        }

        solve(N, hs, showResult, A);
    }

    public static void solve(int n, int numOfSet, long k, int[] a) {
        long[] dp = new long[n];
        for (int i = 0; i < numOfSet; i++) {
            int winner = a[i];
            dp[winner - 1] = dp[winner - 1] + 1;
        }

        PrintWriter out = new PrintWriter(System.out);
        for (long element : dp) {
            if (numOfSet - k >= element)
                out.println("No");
            else
                out.println("Yes");
        }
        out.flush();
    }
}

