    ArrayList<Integer> lgt = new ArrayList<>();
    for (int i = 0; i < enqueue - 1; i++) {
      lgt.add(sc.nextInt());
    }
    int Time = 0;
    int prev = -1;
    for (int i = 0; i < enqueue; i++) {
      int now = std_dev.get(i);
      Time += vis.get(now);
      if (prev >= 0 && now == prev + 1) {
        Time += lgt.get(prev);
      }
      prev = now;
    }
    System.out.println(Time);
  }
}

