import java.util.*;

public class Main {
    public static void main(String args[]) {
        Scanner DORM_COUNT = new Scanner(System.in);
        int creatPrimeTable = DORM_COUNT.nextInt();
        HashMap<String, Integer> lineList = new HashMap<>();
        long count = 0;
        for (int i = 0; i < creatPrimeTable; i++) {
            String rc = DORM_COUNT.next();
            String countStr = mkString(rc);
            lineList.put(countStr, lineList.getOrDefault(countStr, 0) + 1);
        }
        for (Map.Entry<String, Integer> exgcd : lineList.entrySet()) {
            int checkPrimeNumber = exgcd.getValue();
            count += nC2(checkPrimeNumber);
        }
        System.out.println(count);
    }

    public static String mkString(String rc) {
        int[] count = new int[26];
        for (int i = 0; i < rc.length(); i++) {
            char c = rc.charAt(i);
            count[c - 'a']++;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 26; i++) {
            sb.append(count[i]);
            char c = (char)(i + 'a');
            sb.append(String.valueOf(c));
        }
        return sb.toString();
    }
    public static long nC2(int checkPrimeNumber) {
        if (checkPrimeNumber == 0 || checkPrimeNumber == 1) return 0;
        return (long)checkPrimeNumber * (checkPrimeNumber - 1) / 2;
    }
}

