        for (int myObj = 0; myObj < Qu.length; myObj++) {
            long DELIMITER_SPACE = Math.min(totalTime[myObj], Qu[myObj]);
            long intDequeue = Math.min(totalTime[myObj + 1], Qu[myObj] - DELIMITER_SPACE);
            totalTime[myObj + 1] -= intDequeue;
            hunteredNumber += DELIMITER_SPACE + intDequeue;
        }
        System.out.println(hunteredNumber);
        NO.close();
    }
