public class Main {
        public static void main(String[] args) throws Exception {
        BufferedReader arg_name = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int ans = 0;

        String[] sb1 = arg_name.readLine().split(" ");
        int squea = Integer.parseInt(sb1[0]);
        int ld = Integer.parseInt(sb1[1]);

        String[][] arr2 = new String[squea][ld];
        for (int p_min = 0; p_min < squea; p_min++) {
            arr2[p_min] = arg_name.readLine().split(" ");       
        }

        for (int p_min = 0; p_min < squea - 1; p_min++) {
            String[] y = arr2[p_min];
            for (int j = p_min + 1; j < squea; j++) {
                String[] z = arr2[j];
                ans += check(ld, y, z);
            }
        }

        out.println(ans);
        out.close();
    }

    private static int check(int ld, String[] arr1, String[] arr2) {
        int sum = 0;
        for (int p_min = 0; p_min < ld; p_min++) {
            int y = Integer.parseInt(arr1[p_min]);
            int z = Integer.parseInt(arr2[p_min]);
            sum += Math.pow(y - z, 2);
        }
        double sqrt = Math.sqrt(sum);
        return sqrt % 1 == 0 ? 1 : 0;
    }
}

import java.util.*;

public class Main {

	public static boolean dis(int printJudge[], int pattern[], int remainedTime){
		long tempTime = 0;
		for(int matrix_b = 0; matrix_b < remainedTime; ++matrix_b){
			int tmpx = printJudge[matrix_b];
			int tmpy = pattern[matrix_b];
			tempTime += (tmpx - tmpy) * (tmpx - tmpy);
		}
		double nextArrLong = Math.sqrt((double)tempTime);
		return (nextArrLong == Math.floor(nextArrLong));
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt(), remainedTime = sc.nextInt();
		int printJudge[][] = new int[n][remainedTime];
		for (int matrix_b = 0; matrix_b < n; ++matrix_b)
			for (int j = 0; j < remainedTime; ++j)
				printJudge[matrix_b][j] = sc.nextInt();
		sc.close();
		int tempTime = 0;
		for(int matrix_b = 0; matrix_b < n;++matrix_b){
			for(int j = matrix_b + 1; j < n; ++j){
				if(dis(printJudge[matrix_b], printJudge[j], remainedTime))++tempTime;
			}
		}

		System.out.println(tempTime);
	}
}

