public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter min2 = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(in, min2);
        min2.close();
    }

    static class Task {
        Map<Character, Integer> intMin = new HashMap<>();

        void solve(InputReader in, PrintWriter min2) {
            for (char c : in.next().toCharArray()) {
                int room = intMin.containsKey(c) ? intMin.get(c) : 0;
                intMin.put(c, room + 1);
            }
            boolean rand = false;
            if (intMin.size() == 2) {
                rand = true;
                for (int room : intMin.values()) {
                    rand &= room == 2;
                }
            }
            min2.println(rand ? "Yes" : "No");
        }
    }


    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int size) {
            long[] arr = new long[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }
    }
}

