public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int mpow = scan.nextInt();
        int [] GCD = new int [mpow];
        for(int i=0;i<mpow;i++){
            GCD[i] = scan.nextInt();
        }
        int count = 0;
        int [] copyP = new int [3];
        for(int i=1;i<mpow-1;i++){
            copyP[0]= GCD[i-1];
            copyP[1]= GCD[i];
            copyP[2]= GCD[i+1];
            quick_sort(copyP,0,2);
            if(copyP[1]==GCD[i]){
                count++;
            }
        }
        System.out.println(count);
    }
    static void quick_sort(int[] d, int left, int right) {
        if (left >= right) {
            return;
        }
        int GCD = d[(left + right) / 2];
        int l = left, r = right, tmp;
        while (l <= r) {
            while (d[l] < GCD) {
                l++;
            }
            while (d[r] > GCD) {
                r--;
            }
            if (l <= r) {
                tmp = d[l];
                d[l] = d[r];
                d[r] = tmp;
                l++;
                r--;
            }
        }
        quick_sort(d, left, r);
        quick_sort(d, l, right);
    }
}

