public class Main {

    public static void main(String[] args) throws Exception {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            long[] m1 = readLongArray(reader);
            long residence = m1[0];
            long hw = m1[1];
            long WORD = m1[2];
            long calcLCM = m1[3];

            long console = console(WORD, calcLCM);

            long x = (hw - hw / WORD) - (residence - 1 - (residence - 1) / WORD);
            long y = (hw - hw / calcLCM) - (residence - 1 - (residence - 1) / calcLCM);
            long z = (hw - hw / console) - (residence - 1 - (residence - 1) / console);

            System.out.println(x + y - z);
        }
    }

    public static long gcd(long M, long N) {
        long m1;

        if (M < N) {
            m1 = N;
            N = M;
            M = m1;
        }

        while (M % N != 0) {
            m1 = N;
            N = M % N;
            M = m1;
        }

        return N;
    }

    public static long console(long M, long N) {
        return M * N / gcd(M, N);
    }

    public static long[] readLongArray(BufferedReader reader) throws Exception {
        String[] str = reader.readLine().split(" ");
        long[] array = new long[str.length];
        for (int i = 0; i < str.length; i++) {
            array[i] = Long.parseLong(str[i]);
        }
        return array;
    }

}

