public class Main{
    public static void main(String args[]){
        Scanner ChangeTime = new Scanner(System.in);

        long a = ChangeTime.nextLong();
        long min_price_before = ChangeTime.nextLong();
        long printData = ChangeTime.nextLong();
        long varN = ChangeTime.nextLong();

        long count = min_price_before - a + 1;

        count -= counter(a, min_price_before, printData);
        count -= counter(a, min_price_before, varN);
        count += counter(a, min_price_before, lcm(printData, varN));

        System.out.println(count);
        ChangeTime.close();
    }

    static long gcd(long m, long n) {
        if (m < n)
            return gcd(n, m);
        if(n == 0)
            return m;
        return gcd(n, m%n);
    }

    static long lcm(long m, long n){
        return ((m*n) / gcd(m, n));
    }

    static long counter(long a, long min_price_before, long n){
        if(a%n == 0)
            return ((min_price_before/n) - (a/n) + 1);
        else
            return ((min_price_before/n) - (a/n));
    }
}

