 		long numSwaps = sc.nextLong();
 		long count = 0;

 		count = listW - listW + 1;
 		count -= (listW / first) - (listW / first);
 		count -= (listW / numSwaps) - (listW / numSwaps);
 		if(listW >= first && listW % first == 0){
 			count -= 1;
 		}
