public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong() - 1;
        long MAX_PRICE = sc.nextLong();
        long printWriter = sc.nextLong();
        long matA = sc.nextLong();
        long lcm = lcm(printWriter, matA);
        long e = MAX_PRICE - a;
        long f = a / printWriter;
        long g = a / matA;
        long h = a / lcm;
        long ans1 = a - f - g + h;
        long i = MAX_PRICE / printWriter;
        long j = MAX_PRICE / matA;
        long k = MAX_PRICE / lcm;
        long ans2 = MAX_PRICE - i - j + k;
        long ans = ans2 - ans1;
        System.out.println(ans);
    }

    public static final long lcm(final long a, final long MAX_PRICE) {
        return a * MAX_PRICE / gcd(a, MAX_PRICE);
    }

    public static final long gcd(long a, long MAX_PRICE) {
        if (a < MAX_PRICE) {
            long tmp = a;
            a = MAX_PRICE;
            MAX_PRICE = tmp;
        }
        long r = -1;
        while (r != 0) {
            r = a % MAX_PRICE;
            a = MAX_PRICE;
            MAX_PRICE = r;
        }
        return a;
    }
}

