            senCount = Hs/(building_4*y_old/saiyaku(building_4,y_old)) - ttime/(building_4*y_old/saiyaku(building_4,y_old));
        }
        long count = Writer + operand2 - senCount;
        System.out.println(Hs-ttime-count+1);

    }

    public static long max(long kadai, long h_y) {
        if(kadai <= h_y) {
            return h_y;
        }else {
            return kadai;
        }
    }

    public static long saiyaku(long kadai, long h_y) {
        long w = 0;
        if(kadai < h_y) {
            w = kadai;
            kadai = h_y;
            h_y = w;
            return saiyaku(kadai, h_y);
        }
        w = h_y;
        h_y = kadai % h_y;
        kadai = w;
        if(h_y == 0) {
            return kadai;
        }else {

            return saiyaku(kadai, h_y);
        }
    }


}

