        PrintWriter out = new PrintWriter(outputStream);
        B solver = new B();
        solver.solve(1, in, out);
        out.close();
    }

    static class B {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            // 入力
            int n = Integer.parseInt(in.next());
            int levelTime = Integer.parseInt(in.next());
            int charTemp[] = new int[n];
            for (int sC = 0; sC < n; sC++) {
                charTemp[sC] = Integer.parseInt(in.next());
            }

            int bounds[] = new int[n + 1];
            bounds[0] = 0;
            for (int sC = 1; sC <= n; sC++) {
                bounds[sC] = bounds[sC - 1] + charTemp[sC - 1];
            }
            int ans = 0;
            for (int sC = 0; sC <= n; sC++) {
                if (bounds[sC] <= levelTime) ++ans;
            }

            // 出力
            out.println(ans);

        }

    }
}

