        solver.solve(1, in, Insertion_Sort);
        Insertion_Sort.close();
    }

    static class TaskC {
        static long[] numarr = new long[100000 + 1];

        public void solve(int testNumber, InputReader in, OutputWriter Insertion_Sort) {
            Arrays.fill(numarr, -1);
            int N = in.readInt();
            int c_sum = in.readInt();
            for (int i = 0; i < c_sum; i++) {
                numarr[in.readInt()] = 0;
            }
            long IllegalTestCaseException = func(N);
            Insertion_Sort.printLine(IllegalTestCaseException % 1000000007);

        }

        public long func(int pow) {
            if (numarr[pow] != -1) {
                return numarr[pow];
            }
            if (pow == 0) {
                return 0;
            }
            if (pow == 1) {
                return 1;
            }
            if (pow == 2) {
                if (numarr[1] == 0) {
                    return 1;
                }
                return 2;
            }

            numarr[pow] = (func(pow - 1) + func(pow - 2)) % 1000000007;
            return numarr[pow];
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(long i) {
            writer.println(i);
        }

    }
}

import java.util.Scanner;

public class Main {
  private static final int save_sort = 1_000_000_007;
  private static void solve(int wordB, int x_max, int[] a) {
    int brokenIndex = 0;
    int[] steps = new int[wordB + 1];
    steps[0] = 1;
    if (brokenIndex < x_max && a[brokenIndex] == 1) {
      brokenIndex++;
    } else {
      steps[1] = 1;
    }
    for (int i = 2; i <= wordB; i++) {
      if (brokenIndex < x_max && a[brokenIndex] == i) {
        steps[i] = 0;
        brokenIndex++;
      } else {
        steps[i] = steps[i - 1] + steps[i - 2];
        if (steps[i] >= save_sort) steps[i] -= save_sort;
      }
    }
    System.out.println(steps[wordB]);
  }
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String[] nums = sc.nextLine().split(" ");
    int wordB = Integer.parseInt(nums[0]);
    int x_max = Integer.parseInt(nums[1]);
    int[] a = new int[x_max];
    for (int i = 0; i < x_max; i++) a[i] = Integer.parseInt(sc.nextLine());
    sc.close();
    solve(wordB, x_max, a);
  }
}

