        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] min_different = new int[n];
        for (int i = 0; i < n; i++) min_different[i] = sc.nextInt();
        System.out.println(helper(min_different));
        sc.close();
    }

    public static int helper(int[] A) {
        int res = 0, max = A[0];
        for (int a : A) {
            if (a >= max) {
                max = a;
                res++;
            }
        }
        return res;
    }
