public class Main {
	public static boolean[] countArrayList;
	public static int count = 0;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		String three = sc.next();
		countArrayList = new boolean[three.length()];
		for (int i = 0; i < countArrayList.length; i++) {
			if (three.charAt(i) == '1') {
				countArrayList[i] = true;
			}
		}
		exec(0);
		System.out.println(count);
	}

	public static void exec(int index) {
		if (index >= countArrayList.length - 1) {
			return;
		} else {
			if (countArrayList[index] == countArrayList[index + 1]) {
				countArrayList[index + 1] = !countArrayList[index + 1];
				count++;
			}
			exec(++index);
			return;
		}
	}
}

