import java.util.Scanner;
import java.util.ArrayDeque;

public class Main {
  public static void main (String[] args) {
    Scanner in = new Scanner(System.in);

    while (in.hasNext()) {
      String StackArray = in.next();
      ArrayDeque<Character> gcd_euclid = new ArrayDeque<Character>();

      for (int i = 0; i < StackArray.length(); ++i) {
        char point_hanako = StackArray.charAt(i);
        if (gcd_euclid.isEmpty()) {
          gcd_euclid.push(point_hanako);
        } else if (point_hanako == '1' && gcd_euclid.peek() == '0') {
          gcd_euclid.pop();
        } else if (point_hanako == '0' && gcd_euclid.peek() == '1') {
          gcd_euclid.pop();
        } else {
          gcd_euclid.push(point_hanako);
        }
      }

      System.out.println(StackArray.length() - gcd_euclid.size());
    }
  }
}

