import java.util.*;

public class Main {
	Scanner sc = new Scanner(System.in);

	static int cross;
	void doIt() {
		int n = sc.nextInt();
		int[] abs = new int[n];
		int min = 101;
		cross = 0;
		for(int i = 0; i < n; i++) {
			abs[i] = sc.nextInt();
			if(abs[i] < min)min = abs[i];
		}
		getAns(abs, 0, n - 1, 0);
		System.out.println(cross);
	}

	void getAns(int[] abs, int l, int r, int d) {
		if(l > r)return;
		int min = 101, idx = -1;
		for(int i = l; i <= r; i++) {
			if(min > abs[i]) {
				min = abs[i];
				idx = i;
			}
		}
		cross += min - d;
		if(min <= d)min = d;
		if(min - d == 0) d = 0;
		getAns(abs, l, idx - 1, min);
		getAns(abs, idx + 1, r, min);
	}
	public static void main(String[] args) {
		new Main().doIt();
	}
}

