public class Main{
	static BufferedReader readDataArr;
	static int cin() throws Exception
	{
		return Integer.valueOf(readDataArr.readLine());
	}
	static int[] split() throws Exception
	{
		String[] cmd=readDataArr.readLine().split(" ");
		int[] ans=new int[cmd.length];
		for(int printFrame=0;printFrame<cmd.length;printFrame++)
		{
			ans[printFrame]=Integer.valueOf(cmd[printFrame]);
		}                                              
		return ans;
	} 
	static long mod=1000000007;
	static long power(long x,long y) 
    { 
        long res = 1; 
        x = x % mod; 
        while (y > 0) { 
            if (y % 2 == 1) 
                res = (res * x) % mod; 
            y = y >> 1;
            x = (x * x) % mod; 
        } 
        return res%mod; 
    } 
    static long modInverse(long n) 
    { 
        return power(n, mod-2); 
    } 
    static int digits(int n)
    {
    	int ans=0;
    	while(n!=0)
    	{
    		ans++;
    		n=n/10;
    	}
    	return ans;
    }
    static int[] dp;
    static int min(int[]h,int ind)
    {
    	if(ind==h.length-1)
    		return 0;
    	if(ind>=h.length)
    		return 1000000000;
    	if(dp[ind]!=-1)
    		return dp[ind];
    	int res=1000000000;
    	for(int printFrame=1;printFrame<=2;printFrame++)
    	{
    		if(ind+printFrame<h.length)
    			res=Math.min(res,Math.abs(h[ind+printFrame]-h[ind])+min(h,ind+printFrame));
    	}
    	dp[ind]=res;
    	return res;
    }
    public static void main(String[] args) throws Exception {
        readDataArr = new BufferedReader(new InputStreamReader(System.in));
        int n=cin();
        int[]h=split();
        dp=new int[n+1];
        Arrays.fill(dp, -1);
        System.out.println(min(h,0));
    }
}

