import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
	public static int minCost(int stones[], int yousosu) {
		int cost[] = new int[stones.length];
		cost[0] = 0;
		cost[1] = Math.abs(stones[1] - stones[0]);
		for (int i = 2; i < stones.length; i++) {
			cost[i] = Integer.MAX_VALUE;
			for (int j = 1; j <= yousosu; j++) {
				if (i - j >= 0) {
					cost[i] = Math.min(Math.abs(stones[i - j] - stones[i]) + cost[i - j], cost[i]);
				}
			}
		}
		return cost[stones.length - 1];
	}

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n, yousosu;
		String array[] = br.readLine().split(" ");
		n = Integer.valueOf(array[0]);
		yousosu = Integer.valueOf(array[1]);
		int stones[] = new int[n];
		array = br.readLine().split(" ");
		for (int i = 0; i < n; i++) {
			stones[i] = Integer.valueOf(array[i]);
		}
		System.out.println("" + minCost(stones, yousosu));

	}

}

import java.util.*;

class Main{
	static int []segmentTree;

	static void build(int []nums) {
		int n = nums.length;
		for (int i=0; i<n; i++)
			segmentTree[n+i] = nums[i];
		for (int i=n-1; i>0; i--) {
			segmentTree[i] = segmentTree[2*i] + segmentTree[2*i+1];
		}
	}

	static int query(int l, int r, int n) {
		int sum = 0;
		for (l+=n, r+=n; l<r; l>>=1, r>>=1) {
			if ((l&1) == 1) {
				sum += segmentTree[l++];
			}
			if ((r&1) == 1) {
				sum += segmentTree[--r];
			}
		}
		return sum;
	}

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n, sumR;
		n = in.nextInt();
		sumR = in.nextInt();
		int []nums = new int[n];
		for (int i=0; i<n; i++) nums[i] = in.nextInt();
		int dp[] = new int[n+1];
		for (int i=1; i<n; i++) {
			dp[i] = Integer.MAX_VALUE;
			for (int j=1; j<=sumR; j++) {
				if (i-j >= 0) {
