    char[] eps = scanner.next().toCharArray();
    if (solve(s, eps)) {
      System.out.println("Yes");
    } else {
      System.out.println("No");
    }
  }

  private static boolean solve(char[] s, char[] eps) {
    for (int i = 0; i < s.length; i++) {
      boolean ans = true;
      for (int j = 0; j < s.length; j++) {
        if (s[j] != eps[(j + i) % eps.length]) {
          ans = false;
          break;
        }
      }
      if (ans) return true;
    }
    return false;
  }
}

