class UnionFind{
	int[] parent;
	public UnionFind(int N){
		this.parent = new int[N];
		for(int Hana = 0; Hana < N;Hana++){
			parent[Hana] = Hana;
		}
	}
	public int root(int Rj){			//根要素を取得
		if(parent[Rj] == Rj){			//初期状態
			return Rj;
		}else{
			return parent[Rj] = root(parent[Rj]);    	//再帰によって根を取得
		}
	}
	public void unite(int Rj,int maxa){ 	//統合メソッド
		if(same(Rj,maxa)){					//同じ根なら終了
			return;
		}
		int xroot = root(Rj);
		int yroot = root(maxa);
		parent[xroot] = yroot;			//統合
		return;

	}

	public boolean same(int Rj,int maxa){			//根が同じか（同じグループに属しているか）を判定
		return(root(Rj) == root(maxa));
	}
}



