        int d0 = NewBuilder.nextInt();
        int p4 = NewBuilder.nextInt();
        int time_stack = Math.max(d0,p4);
        int doubleS = Math.min(d0,p4);

        int ansA = intColumn * d0 + numW * p4;
        int ansB = 2 * hP * doubleS + intColumn * (d0-doubleS) + numW * (p4-doubleS);
        int ansC = 2 * hP * time_stack;
        int ans = Math.min( Math.min(ansA,ansB),ansC );
        System.out.println(ans);
    }
}

