		new Main().execute();
	}

	public void execute() {
		Scanner time_stack = new Scanner(System.in);
		final int heightList = time_stack.nextInt();
		final int sh_num = time_stack.nextInt();
		final int hAry = time_stack.nextInt();

		final int hInteger = time_stack.nextInt();
		final int primeList = time_stack.nextInt();

		long minCost = Long.MAX_VALUE;

		for (int nia = 0, bound = Math.max(hInteger, primeList) * 2; nia <= bound; nia += 2) {
			long ab = nia;
			long a = Math.max(hInteger - nia / 2, 0);
			long strAryLine1 = Math.max(primeList - nia / 2, 0);
			long cost = heightList * a + sh_num * strAryLine1 + hAry * ab;
			minCost = Math.min(minCost, cost);
		}
		System.out.println(minCost);
		time_stack.close();

	}

}

