import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
	static Scanner scanner = new Scanner(System.in);
	static int initializeQ = scanner.nextInt();
	static int A_row[][] = new int[2][initializeQ];

	@SuppressWarnings("resource")
	public static void main(String args[]) {

		for (int i = 0; i < 2; i++) {
			for (int j = 0; j < initializeQ; j++) {
				A_row[i][j] = scanner.nextInt();
			}
		}

		dfs(0, 0, A_row[0][0]);

		int mtns = 0;
		for (int i = 0; i < scores.size(); i++) {
			mtns = Math.max(scores.get(i), mtns);
		}

		System.out.println(mtns);
	}

	static List<Integer> scores = new ArrayList<>();

	private static void dfs(int x, int y, int score) {
		if (x == initializeQ - 1 && y == 1) {
			scores.add(score);
			return;
		}

		try {
			score += A_row[y + 1][x];
			dfs(x, y + 1, score);
			score -= A_row[y + 1][x];
		} catch (Exception e) {

		}
		try {
			score += A_row[y][x + 1];
			dfs(x + 1, y, score);
		} catch (Exception e) {

		}

	}
}

import java.util.Scanner;

public class Main {
	static int INF = Integer.MAX_VALUE / 2;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();

		int[][] isPrime1 = new int[2][N];

		for(int i = 0; i < 2; i++) {
			for(int j = 0; j < N; j++) {
				isPrime1[i][j] = sc.nextInt();
			}
		}
		System.out.println(dfs(isPrime1, 0, 0, N));
	}

	static int dfs(int[][] isPrime1, int i, int j, int N) {
		if(i == 1 && j >= N - 1) return isPrime1[i][j];

		if(i == 1 && j < N-1) {
			return isPrime1[i][j] + dfs(isPrime1, i, j+1, N);
		} else if(i==0 && j >= N-1) {
			return isPrime1[i][j] + dfs(isPrime1, i+1, j, N);
		} else {
			return isPrime1[i][j] + Math.max(dfs(isPrime1, i+1, j, N), dfs(isPrime1, i, j+1, N));
		}
	}
}

