    for (int i = 0; i < persons; i++) {
      if (max[i] < '0' || max[i] > '9') return false;
    }
    if (max[persons] != '-') return false;
    for (int i = persons + 1; i < persons + isEmptyQ + 1; i++) {
      if (max[i] < '0' || max[i] > '9') return false;
    }
    return true;
  }
}

