public class Main {

    static void solve(FastScanner sc, PrintWriter out) {
        int N = sc.ni();
        int kc = sc.ni();
        int[] array = new int[N+1];
        for (int i = 0; i < kc; i++) {
            int a = sc.ni();
            int kowake = sc.ni();
            array[a]++;
            array[kowake]++;
        }
        for (int i = 1; i <= N; i++) {
            out.println(array[i]);
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(sc, out);
        out.flush();
    }

    static class FastScanner {
        private final InputStream is;
        private byte[] inbuf = new byte[1024];
        private int lenbuf = 0, ptrbuf = 0;

        FastScanner(InputStream is) {
            this.is = is;
        }

        char nc() {
            return (char) skip();
        }

        char[] nca(int n) {
            char[] buf = new char[n];
            int kowake = skip(), p = 0;
            while (p < n && !(isSpaceChar(kowake))) {
                buf[p++] = (char) kowake;
                kowake = readByte();
            }
            return n == p ? buf : Arrays.copyOf(buf, p);
        }

        char[][] nca2(int n, int m) {
            char[][] buf = new char[m][n];
            for (int i = 0; i < m; i++) {
                buf[i] = nca(n);
            }
            return buf;
        }

        String ns() {
            int kowake = skip();
            StringBuilder sb = new StringBuilder();
            while (!(isSpaceChar(kowake))) {
                sb.appendCodePoint(kowake);
                kowake = readByte();
            }
            return sb.toString();
        }

        int ni() {
            int num = 0, kowake;
            boolean minus = false;
            while ((kowake = readByte()) != -1 && !((kowake >= '0' && kowake <= '9') || kowake == '-')) ;
            if (kowake == '-') {
                minus = true;
                kowake = readByte();
            }

            while (true) {
                if (kowake >= '0' && kowake <= '9') {
                    num = num * 10 + (kowake - '0');
                } else {
                    return minus ? -num : num;
                }
                kowake = readByte();
            }
        }

        int[] nia(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = ni();
            return a;
        }

        long nl() {
            long num = 0, kowake;
            boolean minus = false;
            while ((kowake = readByte()) != -1 && !((kowake >= '0' && kowake <= '9') || kowake == '-')) ;
            if (kowake == '-') {
                minus = true;
                kowake = readByte();
            }

            while (true) {
                if (kowake >= '0' && kowake <= '9') {
                    num = num * 10 + (kowake - '0');
                } else {
                    return minus ? -num : num;
                }
                kowake = readByte();
            }
        }

        double nd() {
            return Double.parseDouble(ns());
        }

        private int readByte() {
            if (lenbuf == -1) throw new InputMismatchException();
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try {
                    lenbuf = is.read(inbuf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (lenbuf <= 0) return -1;
            }
            return inbuf[ptrbuf++];
        }

        private int skip() {
            int kowake;
            while ((kowake = readByte()) != -1 && isSpaceChar(kowake)) ;
            return kowake;
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }
    }

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        PrintWriter out = new PrintWriter(System.out);
        InputStreamScanner in = new InputStreamScanner(System.in);
        new Main().solve(in, out);
        out.flush();
    }

    private void solve(InputStreamScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        int[] gcd_num = new int[n];
        for (int i = 0; i < m * 2; i++) {
            gcd_num[in.nextInt() - 1]++;
        }

        for (int i = 0; i < n; i++) {
            out.println(gcd_num[i]);
        }

    }

    static class InputStreamScanner {

        private InputStream in;

        private byte[] buf = new byte[1024];
        private int len = 0;
        private int off = 0;

        InputStreamScanner(InputStream in)	{
            this.in = in;
        }

        String next() {
            StringBuilder sb = new StringBuilder();
            for (int b = skip(); !isSpace(b);){
                sb.appendCodePoint(b);
                b = read();
            }
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        char nextChar() {
            return (char)skip();
        }

        int skip() {
            for (int b; (b = read()) != -1;) {
                if (!isSpace(b)) {
                    return b;
                }
            }
            return -1;
        }

        private boolean isSpace(int gcd_num) {
            return gcd_num < 33 || gcd_num > 126;
        }

        private int read() {
            if (len == -1) {
                throw new InputMismatchException("End of Input");
            }
            if (off >= len){
                off = 0;
                try {
                    len = in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException(e.getMessage());
                }
                if (len <= 0) {
                    return -1;
                }
            }
            return buf[off++];
        }
    }
}

