        Scanner notprime = new Scanner(System.in);
        long calDist = notprime.nextLong();

        long add = 1;
        for(long inputTime = 2; inputTime * inputTime <= calDist; inputTime++) {
            if(calDist % inputTime != 0) continue;

            if(Math.abs(inputTime - calDist/inputTime) < Math.abs(add - calDist/add))
                add = inputTime;
        }
		System.out.println(Math.max(count(calDist/add), count(add)));
    }

    private static int count(long wd) {
        int timeChangeHMS = 0;
        while(wd > 0) {
            timeChangeHMS++;
            wd /= 10;
        }
        return timeChangeHMS;
    }
}

